INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (1, 'Soft-boiled eggs in mustard sauce', '200 g mushrooms|30 g butter|1 tablespoon flour|1 dl white wine|1 dl broth|4 tablespoons cream|2 tablespoons mustard|a little chopped basil|tarragon (or chives and parsley)|8 eggs', 'Fry the mushrooms in the butter. Add the finely chopped shallots. Sprinkle 1 tbsp flour over them, stir everything together and pour in the white wine and the broth. Season with pepper and salt and let it simmer for 10 minutes. Meanwhile, soft-boil the eggs. Add 4 tbsp cream and the mustard to the sauce. Arrange 2 peeled soft-boiled eggs in each small dish. Pour the sauce over them. Sprinkle with a little basil and tarragon. I actually prefer parsley and chives! Serve immediately. Delicious with toast or fresh bread.', 14, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (2, 'Stuffed rolls', '2 rolls|table oil|300 g shrimp|2 tablespoons butter|1/2 tsp curry powder|3 dl fresh cream|2 tablespoons chopped dill or parsley', 'Cut the top off the rolls and hollow them out. Brush the inside with a little oil and warm them briefly. (Works well in the toaster.) Meanwhile, sauté the shrimp in the butter and dust them with the curry. Pour in half of the cream and let it thicken. Add the rest of the cream and reduce until creamy. Stir in the dill or parsley and fill the rolls.', 14, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (3, 'Spoon egg', 'Eggs (according to number of persons)|butter|flour|a little broth|fresh cream|parsley|chives|dill|1 tablespoon capers|a little lemon juice|pepper and salt', 'Make a roux with the butter, flour, and warm broth. Mix egg yolk into the cream and stir into the slightly cooled roux. Meanwhile, hard-boil the eggs (10 min. from the moment the water boils). Add all the fresh herbs, the capers, the lemon juice, salt, and pepper to the sauce. Peel the eggs while still as warm as possible, cut them into wedges, and place them in the warm sauce. Simple but delicious. Tastes great with fried potatoes.', 14, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (4, 'Butterfly to eat', 'A bread roll|8 slices of sausage|a piece of cheese', 'Using a knife, cut into the sides of the rolls about 2 cm deep. The center part remains as it is. For each roll, place 4 smaller slices of sausage on top of four larger ones. Do this so that the smaller sausage touches the edge of the larger slice at one point. With a small knife, slide the sausage slices into the roll, 2 on the left and 2 on the right. The butterfly''s wings are now ready. For the antennae, cut pieces of cheese measuring 4 x 1 x 1 cm on a cutting board. At one end of the roll, make two small holes with the tip of the knife. Insert the cheese pieces there. Now our butterfly also has tasty antennae.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (5, 'Party snake', '1 French loaf|Toothpicks|Ham|2 olives|Washed and dried lettuce|Peeled tomato in slices|Hard-boiled eggs|Cheese|Mayonnaise', 'Cut a French loaf into equal pieces. Cut an opening in the first piece and insert the ham cut into the shape of a snake tongue. Use the two olives for the eyes and secure them left and right in this first piece with toothpicks. Spread the other bread pieces with mayonnaise and top them with lettuce, tomato, ham, cheese, and a few slices of hard-boiled egg. Then insert a toothpick and fasten them together so that you get a snake shape.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (6, 'Cauliflower with ground beef', '750 grams ground beef|1 finely chopped onion|1 stock cube|1 tablespoon Worcestershire sauce|1 small can tomato paste|1 tablespoon flour|1 cauliflower|1 béchamel sauce|grated cheese', 'Brown the minced meat in a knob of butter until crumbly. Add the onion and cook until both the meat and onion are nicely golden brown. Add a crumbled stock cube, 1 tbsp Worcestershire sauce, 1 small can tomato paste and 1 tbsp flour dissolved in a little water. Stir well. Season to taste and let simmer gently for 5 more minutes. Meanwhile, cook the cauliflower until tender and prepare a béchamel sauce. Spoon the minced meat into an oven dish, place the cauliflower on top, pour over the béchamel sauce, and sprinkle with grated cheese. Let gratinate briefly.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (7, 'Gratinated chops', '150 grams freshly grated Gruyère|1 egg|2 tablespoons cream|Chops|Salt|Freshly ground pepper', 'Preheat the oven to 250°. In a bowl, beat the egg with the cheese and cream. Season with nutmeg, pepper, and salt. Heat the butter in a frying pan. Sprinkle the meat with paprika powder and fry it until half-cooked in the butter. Place the chops in an oven dish. Spread each one with the cheese mixture. Drizzle with the pan juices. Let cook in the hot oven for about 15 minutes. The same method also works well for chicken fillet.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (8, 'Ground meat Nice-style', '1 egg|Milk|Salt and pepper|1 tsp dried basil|breadcrumbs|1 chopped onion|1 crushed garlic clove|500 grams ground meat|Some potatoes|2 large onions|margarine|1/4 tsp dried tarragon|1/4 tsp dried basil|2 tbsp chopped parsley|Some tomatoes|Grated cheese', 'Mix the minced meat with egg (yolk), a little milk, breadcrumbs, salt, pepper, some basil, a little finely chopped onion, and the garlic. Knead everything into a homogeneous mixture. Spread the meat evenly in a flat pie dish. Cook the potatoes until almost done and arrange them in slices on the meat. Slice the onions into rings. Sauté briefly and arrange on the potatoes. Sprinkle with some pepper, nutmeg, the tarragon, basil, and parsley. Place the tomato slices on top and brush with some melted butter. Season to taste. Sprinkle with grated cheese and a few small knobs of butter. Bake and gratinate in the oven for 30 minutes. Sprinkle with parsley and serve immediately.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (9, 'Mini spring rolls - Filipino style', '1/2 kg ground beef/pork/chicken|1 red bell pepper|1 onion|1 clove garlic|1/4 kg green beans|1 carrot|1 pack soybean sprouts|soy sauce|a little pepper and salt|1 egg|a little cooking oil', 'Cut the vegetables into small pieces (except the soybean sprouts). Heat the pan with a little oil and add garlic, onion, and meat. When this is half-cooked, add the finely chopped vegetables and soy sauce. Add pepper and salt and let cook until half done. Then remove the vegetable mixture from the pan and let it cool for 2 hours. Squeeze out the liquid and set aside. Beat the egg yolk in a small bowl. Take the mini spring roll wrappers one by one and fill them with the vegetable mixture. Use the egg yolk to seal the edges together. Then fry the spring rolls in deep-frying fat (180°C) for about 3 to 5 minutes.', 1, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (10, 'Pork chop with chives and tomato butter', '125 g butter or margarine|Salt|A tiny pinch of cayenne pepper|Tomato paste|1 teaspoon paprika powder|4 pork chops|1 teaspoon curry powder|Pepper|Fresh chives', 'Mix 125 g butter with salt, tomato paste, paprika powder, pepper, and a pinch of cayenne pepper. Put into a piping bag and pipe 4 small towers onto a plate. Place in the refrigerator. Rub the chops with curry powder, salt, and pepper. Fry the chops until done. Meanwhile, snip the chives finely over a flat plate. Just before serving, roll the chops in the chives. Garnish with a butter tower.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (11, 'Ragout', '500 g veal fricandeau|1/2 l vegetable broth|500 g mushrooms|2 onions|50 g butter|20 g flour|2 egg yolks|1/8 l whipping cream|4 tbsp white wine|salt and pepper|1-2 tsp lemon juice|Worcestershire sauce|40 g grated cheese', 'Cut the fricandeau into cubes and brown on all sides in the steam pot. Then pour in the broth and steam until tender in 30 minutes. Clean the mushrooms and halve them. Peel and chop the onions. Sauté the onions in the butter until translucent, add the mushrooms, and cook them as well. Sprinkle the flour over the mushrooms while stirring. Remove the meat from the broth with a slotted spoon. Pour the broth into the mushrooms while stirring and let the whole thing boil for 10 minutes. Beat the egg yolks with the cream and stir into the sauce off the heat. Season with salt, pepper, and Worcestershire sauce. Stir the meat into the sauce. Transfer the ragout to an oven dish and sprinkle grated cheese over it. Let gratinate in a preheated oven at 200° for 10 to 15 minutes. Delicious with rice.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (12, 'Popsicles', '800 ml pure fruit juice - for example orange, cranberry, or pear juice, or a small amount of pure fruit syrup diluted with water|Spoon|Ice pop molds - 10 pieces|Freezer|Press (optional)|200 grams brown caster sugar (optional)', 'Water ice is really nothing more than frozen fruit juice or syrup, optionally sweetened with sugar. To avoid turning your popsicles into a calorie bomb, it is best to use pure fruit juice or syrup: juice that contains only natural sugars and no added sugars. Even tastier is if you squeeze the fruits yourself. You can do this, for example, with oranges, grapefruits, lemons, and limes. For fruits such as pears, apples, cranberries, berries, and grapes, you can buy bottles of pure juice or syrup in most supermarkets or health food stores. Choose your favorite fruit juice and pour about 800 ml into a bowl. You can also combine juices. Cranberry and orange juice, for example, make a delicious combination. Just like pear and apple juice. If you prefer fruit syrup instead of juice, you only need a small amount. Then dilute the small amount of syrup with water until you have 800 ml. This is enough for about 10 popsicles. Some fruit juices can be a bit sour. By adding some sugar to the juice, you can soften the sour edge. If you actually like the sourness, leave out the sugar. Or if you prefer not to consume too much sugar, choose a sweeter fruit such as pears or strawberries. For sweetening the fruit juice, brown caster sugar works best. Brown caster sugar has a much finer structure than granulated sugar. This makes your popsicles more uniform and smoother. If you make popsicles from more acidic juices such as cranberry or grapefruit juice, you can add 200 grams of brown caster sugar if you use 800 ml juice. Add the sugar to the juice in the bowl and stir until fully dissolved. You can buy the plastic ice pop molds in kitchen shops, and also in household stores. Rinse the molds and dry them. Then fill them with the fruit mixture and insert the sticks. Then let the freezer do its work: place the molds in the freezer compartment and only take them out once the popsicles are completely frozen. How long that takes depends on the freezing power of your appliance, but usually they are ready after about three hours. Lick and enjoy!', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (13, 'Stir-fried pork tenderloin with vegetables', 'Marinade|1 coffee spoon soy sauce|1 coffee spoon sherry|1 coffee spoon sesame oil|----------------|Pork tenderloin|2 carrots|300 g snow peas|12 baby corns|12 shiitakes|3 spring onions|Peanut oil|1 clove garlic|Pieces of fresh ginger|Soy sauce|2 to 3 tablespoons cornstarch', 'Mix the ingredients for the marinade. Cut the meat into strips and place them in the marinade. Let it stand for 15 to 20 minutes. Meanwhile, clean the vegetables. Slice the carrots diagonally. Trim the snow peas and leave them whole. Cut the baby corn into rounds. Remove the stems from the shiitakes and halve the caps. Cut the bell peppers into strips and slice the spring onions into rings. Keep a little green aside for garnish. Heat a little oil in the wok and stir-fry the marinated strips of pork fillet over high heat. Remove the strips from the wok and let them drain in a sieve. Finely chop the peeled garlic and fresh ginger. Clean the wok and add a little oil again. Stir-fry the vegetables. First the carrots, then the corn, the snow peas, the bell peppers, the garlic, and the ginger. Keep stirring continuously! Add the mushrooms and finally the spring onions. Dissolve the cornstarch in the stock with a dash of soy sauce. Pour it over the vegetables while stirring. Mix in the meat and let everything heat through for a few more minutes. Finish the dish with the reserved green of the spring onions.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (14, 'Shrimp ragout oriental style', '1 kg shrimp|1 large onion|2 cloves garlic|2 tablespoons butter|1 dl cognac|2 tablespoons paprika powder|1/4 tsp cayenne pepper|2 dl fresh cream|1 (green) bell pepper', 'Sauté the chopped onion together with the minced garlic and the bell pepper cut into strips in the melted butter. Add the shrimp and let stew for 5 minutes. Pour in the cognac, heat through, and flambé. Then stir in the fresh cream and season with cayenne pepper and paprika powder. Let it thicken over high heat and serve with rice or a salad. Delicious and quick to prepare.', 1, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (15, 'Gratinated mussels', '2 kg mussels|3 shallots|1 lemon|2 eggs|2 spoons flour|1 handful breadcrumbs|130 grams butter|50 grams grated Gruyère|1 glass white wine|Parsley|Salt and pepper', 'Put the cleaned mussels in a cooking pot and sprinkle with the chopped shallots, salt, pepper, and the white wine. Cook the mussels over high heat until done. After cooking, let the mussels drain and keep the cooking liquid. Remove the mussels from their shells. Butter an oven dish and place the mussels in it. Prepare a blond roux with part of the butter and 2 spoons of flour. Add the strained cooking liquid little by little. Stir the sauce until smooth and thickened. Add the egg yolks and let the sauce cook briefly over low heat while stirring continuously. Remove the sauce from the heat and mix in the lemon juice. Cover the mussels with the sauce. Sprinkle with breadcrumbs and grated cheese. Divide small knobs of butter over the dish and gratinate in a very hot oven for 5 minutes. Sprinkle with chopped parsley and serve very hot with a dry white wine. Delicious with nicely piped mashed potatoes.', 12, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (16, 'Cauliflower soup with cheese', '3 liters cauliflower cooking liquid|90 grams butter|90 grams flour|100 grams grated cheese|Chopped parsley|1 1/2 dl cream or milk|1 to 2 egg yolks', 'Make a roux and dilute it with the cauliflower cooking liquid, optionally extended with broth. Let the soup boil and add small cauliflower florets as garnish; continue boiling. In the soup tureen, mix the egg yolk(s), cream or milk, parsley, and grated cheese. Pour the boiling soup over it and serve.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (17, 'Stuffed speculoos', '250 grams self-raising flour|Salt to taste|2 tablespoons speculoos spices|150 grams brown caster sugar|150 grams butter|2 tablespoons milk|50 grams white almonds|1 egg yolk', 'Put the self-raising flour, some salt, the speculoos spices, and the brown caster sugar into a bowl. Cut the butter into this mixture with two knives. Add the milk and knead everything into a dough. Press out half of the dough onto a buttered baking tray - in the shape of a bar, rectangle, or heart. Spread the almond paste over it up to 1 cm from the edge. Place the second half of the dough on top and press it firmly around the edges. Decorate with the almonds. Brush the top with the egg yolk beaten with the milk. Place the tray slightly below the center of a moderately hot oven at about 150 degrees C. Baking time: 1/2 to 3/4 hour until the cake is done and golden brown. Let the filled speculoos cool flat.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (18, 'Strawberry bavarois', '3 sheets gelatin of 3 grams each|200 grams strawberries|25 grams granulated sugar|2.5 dl cream|--- For the glaze and coulis ---|1 sheet gelatin of 3 grams|50 grams granulated sugar|200 grams strawberries|dash of Cointreau|--- For finishing ---|250 grams strawberries|lemon balm leaves|satay sticks|4 molds of approx. 8 cm diameter', 'Soak the gelatin sheets (3+1) in cold water. Rinse the strawberries and remove the tops. Boil the water with the sugar into a syrup and let cool. For the coulis, cut 200 g strawberries into pieces, add them to the syrup, and blend finely. Sieve the coulis and flavor with a splash of Cointreau. Squeeze out 1 gelatin sheet, melt it over low heat, and stir it through half of the coulis. Keep the other half of the coulis chilled. Pour a little layer of jelly into the molds. Slice 8 strawberries and place them point-down in a circle against the sides of the molds. For the bavarois, blend the strawberries with the granulated sugar. Whip the cream with the vanilla sugar. It should not be fully stiff. Squeeze out the remaining gelatin sheets, melt them, and carefully stir them into the strawberry puree. Fold the whipped cream into the strawberry puree and fill the molds with the mixture. Smooth the tops and let set in the refrigerator for about 2 hours. Make skewers by alternately threading strawberries and lemon balm leaves onto sticks. Unmold the bavarois by loosening the edges with the tip of a knife and dipping the bottoms of the molds briefly in warm water. Finish with a few drops of coulis and a skewer. Serve the rest of the coulis separately.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (19, 'Stir-fried chicken with vegetables', 'Chicken fillet|2 carrots|300 g snow peas|12 baby corns|12 shiitakes|2 bell peppers|3 spring onions|peanut oil|1 clove garlic|pieces of fresh ginger|6 tablespoons veal or poultry stock|soy sauce|2 to 3 tablespoons cornstarch', 'Mix the ingredients for the marinade. Cut the chicken into strips and place them in the marinade. Let stand for 15 to 20 minutes. Meanwhile, clean the vegetables. Slice the carrots diagonally, trim the snow peas and leave them whole. Cut the baby corns into rounds, remove the stems from the shiitakes and halve the caps. Cut the bell peppers into strips and slice the spring onions into rings. Keep a little green aside for garnish. Heat a little oil in the wok and stir-fry the marinated strips of chicken fillet over high heat. Remove the strips from the wok and let them drain in a sieve. Finely chop the peeled garlic and fresh ginger. Clean the wok and add a little oil again. Stir-fry the vegetables: first the carrots, then corn, snow peas, the bell peppers, the garlic, and the ginger. Keep stirring constantly! Add the mushrooms and finally the spring onions. Dissolve the cornstarch in the stock with a dash of soy sauce. Pour it over the vegetables while stirring. Mix in the chicken and let everything heat through for a few more minutes. Finish the dish with the reserved green of the spring onions.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (20, 'Roman fillet', '1 kg pork roast|Butter|1/8 l white wine|125 g whipping cream|150 g semi-aged cheese|Mustard', 'Cook the roast until done. Make a cut every 2 cm and place a slice of cheese spread with mustard into each cut. Let it gratinate in the oven so the cheese melts. Place the meat on a platter and keep warm. Add the wine to the roasting juices. Thicken the sauce with flour dissolved in the cream. Pour part of the sauce over the meat and serve the rest separately. Tip: Roasting time for pork - 60 min. per kg. ----- Variation: ----- Instead of 1 slice of cheese and 1 slice of ham between the roast - do the following: Finely chop shallots and mushrooms. Prepare a béchamel sauce and mix some of it with the shallot/mushroom mixture. Spread this onto the ham slice and insert it into the roast. Add plenty of cheese to the béchamel sauce and pour over the meat. Grill in the oven.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (21, 'Schnitzels with mozzarella', '2 pork sauté cuts of 100 g|2 tablespoons olive oil|2 cloves garlic|finely chopped|1 pack sieved tomatoes (500 g)|1 tablespoon dried capers|salt and pepper|1 mozzarella ball in 4 slices', 'Flatten the meat. Heat the oil and gently fry the garlic in it. Add the meat and brown on one side. Spread the sieved tomatoes over it. Add capers and oregano and let the meat stew with the lid on the pan for about 8 minutes. Sprinkle with salt and pepper. Place a slice of mozzarella on each piece of meat and let it melt for about 2 minutes with the lid on the pan. Delicious with rice and, for example, green beans. A weekday dish.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (22, 'Serbian pork', '4 pork sauté cuts|2 tablespoons French mustard|1 egg yolk|2 tablespoons flour|1 tsp paprika powder|salt|3 tablespoons butter|50 g smoked bacon|2 onions|2 bell peppers|4 tomatoes (or use only the tomatoes from a can of peeled tomatoes - no juice!)|parsley|--- For the risotto: ---|1 onion|2 tablespoons butter or oil|2 dl rice|4 dl broth|box of peas', 'Start with the risotto: sauté the chopped onion in the butter, add the rice, let it cook briefly, and pour in the broth. Put a lid on the pan and let it simmer for 20 minutes until the rice has absorbed all the broth. Beat the egg with the mustard and spread this mixture over the meat. Coat both sides in the flour seasoned with paprika powder and salt. Heat the butter and brown the meat nicely on both sides. Lower the heat and let it cook gently. Cut the smoked bacon, cleaned bell peppers, peeled onions, and tomatoes into pieces. Fry the onions and bacon in the pan until tender. Add the finely chopped bell peppers, let them cook for a few minutes, and mix in the tomato pieces. Put a lid on the pan and let it stew briefly. Mix the peas into the risotto. Stir in another knob of butter and spoon the risotto onto a warmed serving dish. Place the meat on top and spread the vegetable mixture over it. Finally decorate with onion rings and sprinkle with freshly chopped parsley. Serve immediately.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (23, 'Pork tenderloin with orange sauce', '2 pork tenderloins|mild mustard|candico (brown rock sugar!)|6 oranges|cream', 'Rub the pork tenderloins with a good layer of mustard, then cover generously with rock sugar. Let this marinate for a while. In the meantime, squeeze the oranges (keep 1/2 aside). Slice that half orange into rounds. Preheat the oven to 200 degrees and add the orange juice, but not all of it. When the meat is done, keep it warm. Take a saucepan and pour in the juices from the roasting tray, add cream, and let it reduce a little. You can add more orange juice to taste. Reduce to the desired thickness. Slice the meat and garnish on a warm plate, add some croquettes or pommes duchesse, and nap the sauce over the meat! Finish with a little greenery.', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (24, 'Cod with vegetables', '1 decent carrot|1 large (or 2 thin) leek(s)|2 frozen pieces|Cod (or pollock fillets)|Tomato paste|Cube of vegetable stock dissolved in a little more than 1 dl water and 1 dl white wine (fruits de mer)|Cream or milk', 'Wash the vegetables, cut the leek into thin short strips, and use a peeler to cut the carrot into thin strips and then into small pieces. Stew the vegetables in butter for about 10 minutes, add the broth and wine, and bring to a boil. Place the fish (do not thaw) in the vegetable sauce and cook for about 15 minutes until everything is done. Remove the fish and vegetables from the pot and arrange on a plate. Dissolve the tomato paste together with a generous splash of milk (or cream) in the remaining liquid and thicken with cornstarch. Serve with mashed potatoes.', 12, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (25, 'Cod with mustard sauce', '400 g fish fillets (from the freezer - e.g. cod - redfish - whiting ...)|400 g (frozen) vegetables (e.g. carrots and peas - chopped bell peppers - leek or a mixed vegetable blend)|1/2 l fish broth (cube)|3 tablespoons mustard|2 egg yolks|Butter|Salt and pepper', 'Melt a knob of butter in a deep frying pan. Sauté the vegetables in it. Season to taste and let them stew gently until done. Bring the fish broth to a boil and poach the fish fillets in it. Let them drain well and keep them warm. Reduce the fish broth by half. Off the heat, stir the egg yolks and mustard into the sauce. Heat a little more but do not let it boil! Season to taste and pour the mustard sauce over the fish and vegetables. Serve immediately. This dish is delicious with potato balls or croquettes.', 12, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (26, 'Cod with white wine sauce', '4 nice cod steaks|1/2 l fine fish fumet|1/2 l dry white wine|Freshly ground pepper and salt|100 grams butter|Freshly chopped chives.', 'Season the cod steaks with pepper and salt and poach them in the fumet with the white wine until done. Remove the fish from the pan and let the cooking liquid reduce well. Strain into a smaller pan and whisk in the cold butter a little at a time until a nicely bound sauce forms. Serve with mashed potatoes, briefly gratinated in the oven or under the grill.', 12, 4542);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (27, 'Chicory with salmon filling', '4 heads of chicory|+/- 125 grams mushrooms|2 shallots|1 can salmon|Lemon|A little white sauce|1 egg yolk|2 tablespoons cream|1 knife tip hot curry|grated cheese|parsley|And shrimp if desired', 'Clean the chicory and let it brown nicely in a little butter, seasoning well with pepper and nutmeg while stewing. Once it is nicely browned on all sides, pour in broth and let it cook gently until tender. Cut the heads in half lengthwise if they are thick, so they soften faster. Meanwhile, finely chop the shallot and mushrooms. Open the can of salmon, pour the liquid into a saucepan together with the juice of a lemon, some butter, and the chopped vegetables. Let this stew for 5 minutes with the lid on. Add the white sauce to the stewed vegetables, let it come almost to the boil, and add the egg yolk beaten with cream plus some grated cheese to the preparation. Remove from the heat. Remove the skin and bones from the salmon, divide into pieces, and mix together with the curry into the sauce. Butter an oven dish and make a nice border of well-seasoned mashed potatoes. Place the stewed chicory in the center and spoon the sauce over it. Sprinkle the remaining grated cheese over the top and gratinate briefly under the hot grill. You can make the sauce even more festive by adding shrimp too!', 12, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (28, 'Salmon in white wine sauce', '4 salmon fillets (4x150 grams)|4 dl dry white wine|3 shallots|Butter|Chives|Pepper and salt|250 ml cream (Alpro soya cuisine.)', 'Finely chop the shallots and braise them in a little butter. Add the white wine and reduce by half (optionally thicken with cornstarch). Rub the salmon pieces with pepper and salt and fry them in some butter. Reduce the cream by half and, off the heat, stir in the reduced white wine and the shallots. Pour the sauce over the fried salmon and garnish with the chopped chives. Serve with green tagliatelle or mashed potatoes.', 12, 13722);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (29, 'Sole strips with pistachio butter', '8 sole fillets|100 g dairy butter|150 g shelled pistachios|Pepper and salt', 'Cut the sole fillets into strips and crush the shelled pistachios. Melt the dairy butter and add the sole strips and pistachios. Let the strips cook through and then serve them in egg cups with a small garnish.', 12, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (30, 'Picatta alla Milanese', '4 chicken fillets of 100 g|White pepper|salt|3 tablespoons wheat flour|4 eggs|4 tablespoons grated Parmesan cheese|6 tablespoons salad oil|1/2 dl dry white wine|1 tablespoon whipping cream|1/8 liter whipping cream|100 g butter|50 g Roquefort|2 sprigs parsley', 'Sprinkle the chicken fillets with pepper and salt and dust with some flour. Beat the remaining flour with the eggs, grated cheese, and pepper and salt to taste into a smooth batter. Dip the chicken fillets into the batter and fry them in the hot oil until golden on both sides. Place the fillets on the baking tray and put them in the oven for 15 minutes. For the sauce, bring the wine, crème fraîche, and whipping cream to a boil and reduce over high heat until about half remains. Remove the pan from the heat and whisk in the pieces of butter. Crumble the Roquefort over the pan and stir it into the sauce. Season with pepper and salt and serve with parsley.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (31, 'Coq au vin', 'Chicken fillets|100 g bacon|40 g butter|12 small onions|2 shots brandy|Salt|Freshly ground black pepper|1 clove garlic|2 bay leaves|1/2 l red wine|20 g|butter|250 g mushrooms|1 tsp thyme|3 tablespoons water|2 tablespoons starch|Parsley', 'Rinse the chicken briefly under cold running water and pat dry. Cut the bacon into cubes and render in a large frying pan. Add the butter and brown the chicken pieces nicely on all sides. Meanwhile, peel the onions and halve them. Then let them sauté with the chicken in the butter and pour over the brandy. Flambé. Season with salt, pepper, garlic, and bay leaves. Then pour over the red wine and let braise covered for about 30 minutes. Clean the mushrooms and halve them. Heat the butter in a frying pan and sauté the mushrooms in it. Season with thyme and add them to the chicken 10 minutes before the end of cooking so they can braise along. Arrange the cooked chicken pieces with the onions, bacon, and mushrooms in a serving dish. Loosen the browned bits from the pan, thicken with dissolved starch, let it thicken, and season. Then pour the sauce over the chicken and sprinkle with fresh parsley.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (32, 'Devilishly delicious turkey drumsticks', '2 teaspoons French mustard|2 teaspoons mustard|1 tablespoon tomato ketchup|1/4 teaspoon ginger powder|salt and black pepper|1/4 teaspoon cayenne pepper|4 skinned cooked turkey drumsticks (or chicken fillet)', 'Stir the mustard, tomato ketchup, ginger powder, salt, and pepper together and finish the sauce with a pinch of cayenne pepper. Make shallow cuts in the cooked chicken fillets and brush them with melted margarine. Then roll the fillets through the mustard mixture and let them marinate in it for half an hour. Preheat the grill (oven). Grill (roast) the drumsticks for about fifteen minutes. They are ready when the meat is cooked and the drumsticks are crispy brown. Delicious, summery, great with lettuce and tomatoes and fried potatoes.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (33, 'Gratinated chicken with pesto', '4 Chicken fillets|2 onions|4 tomatoes|6 boiled potatoes|2 mozzarella balls|4 tablespoons pine nuts|2 cloves garlic|3 heads rocket salad coarsely chopped|Olive oil|Pepper and salt', 'Preheat the oven to 200°. Peel the garlic cloves. Dry-roast 2 tablespoons pine nuts in a pan. For the pesto, blend the garlic with the pine nuts, the salad, olive oil, pepper, and salt. Cut the peeled tomatoes into wedges and the potatoes into cubes. Cut the mozzarella balls into slices. Peel the onions and cut them into strips. Cut the chicken fillets into cubes and fry them with the onion rings in hot butter until golden brown. Add the tomato wedges, potato cubes, pesto, and 2 tablespoons pine nuts. Stir everything well and top with the mozzarella. Place the oven dish in the hot oven for 10 minutes and then under the grill for another 2 minutes. Serve immediately.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (34, 'Grilled honey chicken fillet with spinach salad', '2 chicken fillets|1 tablespoon honey|1 clove garlic - crushed|1 fresh red chili pepper - finely chopped|juice of ½ lemon|1 tablespoon olive oil|freshly ground black pepper and salt|--- For the spinach salad ---|1 tablespoon sesame seeds|1 clove garlic - crushed|½ tablespoon soy sauce|1 tablespoon sweet sherry|1 tablespoon sesame oil', 'Mix the honey, garlic, lemon juice, chili pepper, and olive oil. Stir until the honey is absorbed. Let the chicken marinate in this for 30 minutes. Season the fillets with pepper and salt to taste. Fry them in a grill pan (or on the barbecue) for 2 to 3 minutes on each side until nicely cooked and browned. Rinse the spinach and let the leaves drain well. Dry-roast the sesame seeds until lightly golden. Crush them coarsely with a rolling pin or in a mortar. Then place them in a salad bowl. Add the crushed garlic, soy sauce, sherry, and sesame oil and stir into a dressing. Toss the spinach lightly through it. Serve the chicken fillet on a bed of spinach salad. Delicious and summery with French bread and a Moselle wine.', 4, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (35, 'Pasta with salmon cream sauce', '2 tomatoes|1 green bell pepper|1 cup crème fraîche or cooking cream|1 pack herb cheese with herbs (e.g. Paturain or from AH)|250 grams pasta of your choice', 'Sauté the onion and bell pepper in a little oil in a sauté pan. When the mixture is translucent, add the tomatoes. Meanwhile, cook the pasta. Then add the salmon pieces. Once this mixture has fried briefly, add the crème fraîche and the herb cheese and stir until everything has melted well. Optionally season with salt, pepper, oregano, and basil. Drain the pasta and done! Optionally serve with a nice salad and a glass of wine.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (36, 'Pasta with minced meat and gorgonzola sauce', '250 g ground beef|1 egg yolk|1/2 teaspoon Italian herbs|salt and pepper|breadcrumbs|150 grams green tagliatelle|Butter or margarine|1/8 l whipping cream|125 grams gorgonzola cheese', 'Mix in a bowl: minced meat, egg yolk, herbs, salt, pepper, and breadcrumbs. Roll into meatballs. Cook the pasta al dente in a pan. Heat butter in a pan and fry the meatballs until golden brown and done all around. Meanwhile, heat the whipping cream and gorgonzola in a saucepan while stirring. Drain the pasta in a colander and divide over 2 plates. Pour over the sauce and add the meatballs.', 9, 4356);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (37, 'Pizza with mushrooms', 'Ready-made pizza base|2 tablespoons olive oil|1 clove garlic crushed|Tomato sauce|100 grams ham|250 grams mushrooms in slices|A little oregano', 'First make a tomato sauce. For this, stew a chopped onion in a little butter or olive oil and add crushed garlic and a can of peeled tomatoes. Season with salt, pepper, and herbs. Let it simmer until the moisture has evaporated. Roll out the dough slightly and fold up the outer edge a little. Stir the garlic into 1 tbsp oil and brush the pizza base thinly with it. Or use tasty pizza oil to which you don''t need to add anything. Spread the tomato sauce over the pizza base and place the ham on top. Heat 1 tbsp oil and fry the mushrooms for about 4 minutes while stirring. Spoon onto the ham and sprinkle with cheese and oregano. Bake the pizza in the middle of the oven for 15 to 20 minutes until golden brown. Delicious and quick to prepare. Zucchini can also be added.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (38, 'Spaghetti with roasted bell pepper', '2 red bell peppers|2 yellow bell peppers|400 grams spaghetti|olive oil|1 clove garlic|Salt and pepper|100 grams pecorino cheese|Parsley', 'Prick the bell peppers in several places. Roast over a gas flame until the skin turns brown. Place in a sealed plastic bag for about 2 minutes. Remove from the bag and peel off the skin. Remove the seeds and cut the peppers into strips. Cook the spaghetti al dente. Drain. Heat oil in a frying pan. Press the garlic into it. Toss the spaghetti and bell peppers through it. Season with salt and pepper. Sprinkle with pecorino and parsley. If you don''t have pecorino, you can also use Parmesan. Delicious - also good as a summer appetizer.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (39, 'Tagliatelle with garlic sauce', '500 g tagliatelle (or other noodles)|Oil|Salt|1 tablespoon margarine|2 cloves garlic|200 grams herb quark (Boursin - Paturain or something similar)|1/8 l cream|Pepper|Mixed garden herbs (frozen)', 'Bring a large pan of water to a boil. Add salt and some oil and cook the pasta until al dente. Meanwhile, melt the margarine. Press the garlic cloves into it. Let the quark melt and season with pepper and the garden herbs. Drain the pasta and pour the garlic sauce over it. Serve immediately.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (40, 'Tagliatelle with leek and minced meat', '300 grams tagliatelle|Salt and pepper|50 grams butter|1 kg leek in thin rings|2 dl cream|500 g minced meat|+/- 1 dl meat broth|2 tbsp finely chopped basil|Nutmeg|75 g coarsely grated cheese', 'Cook the tagliatelle in plenty of boiling salted water until al dente and drain. Preheat the oven to 200° C. Heat butter and cook the leek in it over low heat for about 5 minutes. Add cream, salt, and pepper and let it stew for another 10 minutes. Heat butter and fry the minced meat crumbly in a few minutes while stirring. Mix the meat with a little cream, broth, basil, salt, pepper, and nutmeg. Place the tagliatelle on the bottom of an oven dish, spread the minced meat over it, cover with leek, and sprinkle cheese on top. Bake for about 30 minutes.', 9, 17193);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (41, 'Salmon ravioli', 'Salmon steak of +/- 300 grams|1 bunch basil|200 g mascarpone|2 eggs|300 grams fine flour|2 dl water|100 grams butter|1 dl cream|2 tomatoes|Bunch parsley|Olive oil|Salt and pepper', 'Preparation (making the dough): Put the flour in a bowl and make a well in the center. In another bowl, add 1 egg, 2 dl water, 1 teaspoon salt, and a splash of olive oil, beat together with a whisk, and pour this mixture into the well in the flour. Mix everything together until a smooth dough forms. Cover the bowl with plastic wrap and refrigerate for a few hours. Cut the salmon into cubes. Add 1 egg, coarsely chopped basil, mascarpone, salt, and pepper. Mix everything well. Roll out the dough into thin sheets, place one lasagna sheet on the work surface. Make sure you have a bowl of beaten egg and a brush ready. Moisten the dough with the brush. Using a spoon, place small heaps of filling on the dough, keeping about 5 cm between them. Take another sheet of dough and place it over the whole thing, pressing well where there is no filling. Now cut the desired shapes with a ravioli wheel, making sure that the outside of the ravioli is well sealed. Bring a pan of plenty of water to a boil. Add some salt. Carefully place the ravioli in it and let them cook for about 4 to 5 minutes. Melt some butter in a frying pan, add two peeled tomatoes cut into cubes and let them cook for about 2 minutes. Add the finely chopped parsley, salt, and pepper. Remove the ravioli from the pan carefully with a slotted spoon and gently add them to the sauce, let the whole thing stand for about 5 minutes, then serve immediately.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (42, 'Fine almond cake', '110 grams butter|140 grams granulated sugar|85 grams ground almonds|3 eggs|40 grams flour|1/2 teaspoon baking powder|Pinch of salt|Powdered sugar for decoration', 'Cream the butter and mix with the sugar until frothy and thick. Add the almonds and beat briefly again. Gradually work the eggs into the batter, beating continuously with the hand mixer. Finally, carefully fold the flour, baking powder, and salt into the egg mixture. Spoon into the greased cake tin (18 cm) and bake in the warm oven (180°) until the cake is golden brown and springy (45 min.). Let cool on a wire rack and dust with powdered sugar before serving.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (43, 'Almond tart with apple', '150 grams almonds|75 grams butter|2 eggs|100 grams sugar|100 grams cream|3 apples (renettes)', 'Place the sifted flour and a pinch of salt in a round bowl, and knead the pieces of butter through it. Add cold water little by little until you can knead it into a ball. Let rest in a cool place for a few hours. Sprinkle flour on the work surface and roll the dough out thinly. Place it in a buttered tart tin. Cut the apples into wedges and arrange them on the dough. Peel the almonds. Blend the almonds, sugar, cream, and eggs and pour this over the apples. Bake for about 40 minutes in a preheated oven at 200° C.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (44, 'Pineapple bavarois with strawberry coulis', '--- For the strawberry coulis: ---|1/2 kg strawberries|Powdered sugar to taste|A few drops of lemon|--- For the pineapple bavarois: ---|4 dl pineapple puree|4 dl whipped cream|7 gelatin sheets|2 dl water|150 grams sugar|A few drops of lemon|---- For decoration: ----', 'Blend - for the coulis - the strawberries, powdered sugar, and lemon, and sieve the coulis. Boil the water and sugar into a syrup. Add the soaked and squeezed gelatin sheets and let it cool. Add the syrup to the pineapple puree together with the lemon and fold in the whipped cream. Pour the mixture into oiled molds and let set in the refrigerator. Turn them out onto a plate. Arrange seasonal fruit and the coulis decoratively around them. Finish with a mint leaf.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (45, 'Apple cake', '125 grams self-raising flour|150 grams fine sugar|1 packet vanilla sugar|75 grams butter|2 eggs|750 grams apples', 'Butter the small cake tin and dust with some flour. Beat the egg yolks and sugar until pale and frothy. Work the mixture for 5 minutes. Stir in the melted butter, and then the self-raising flour. Mix everything well and fold in the stiffly beaten egg whites. Fold the peeled apples cut into small cubes into the batter. Spoon the apple batter into a long cake tin and bake for 40 minutes in an oven at 180°. Place aluminum foil over the cake if it becomes too dark.', 3, 5002);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (46, 'Brownies with hazelnuts', '150 grams milk chocolate with hazelnut pieces|50 grams butter|3 eggs|150 grams granulated sugar|150 grams flour|3 tablespoons cream', 'Preheat the oven to 180°. Melt the butter and chocolate au bain-marie. Beat the egg yolks with the sugar and mix into the chocolate. Sift the flour over it and mix well. Beat the egg whites until stiff and fold into the batter. Grease 8 small molds and dust with flour. Spoon the batter into them and bake for 10 minutes at 180°. Lower the thermostat to 175° and bake for another 10 minutes. Let the molds cool.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (47, 'Brussels waffles', '250 grams flour|20 grams yeast|2 dl lukewarm water|2 dl lukewarm milk|4 eggs|125 grams unsalted butter or fat|A pinch of salt', 'Sift the flour into a bowl and make a well in the center. Dissolve the yeast in the lukewarm water, slowly stir the paste into the flour, and add the lukewarm milk, a pinch of salt, and the egg yolks. Mix everything well. Beat the egg whites until stiff and carefully fold the egg whites and melted fat into the batter. Let rise for 15 to 20 minutes before you start baking. Spoon a small ladle of batter per waffle into the hot waffle iron. Bake these thick, airy waffles in a waffle iron with a large coarse diamond pattern. Serve them warm, with powdered sugar and a dollop of whipped cream. Decorate with fresh fruit if desired. (To make them even lighter, replace the regular water with sparkling water.)', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (48, 'Chocolate mousse', '150 g chocolate|3 eggs|80 grams sugar|1/8 l cream|2 cl cognac or rum', 'Melt the chocolate broken into pieces au bain-marie. Meanwhile, beat 3 egg yolks with the sugar until frothy, until the sugar is dissolved. Whip the cream until stiff. Beat the egg whites until stiff. Stir the cognac or rum into the egg yolk mixture and then pour that through the melted chocolate. The mixture should still be lukewarm when the whipped cream is stirred in. Then fold in the beaten egg whites.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (49, 'Coconut balls', '100 grams grated coconut|25 grams flour|75 grams butter or margarine|50 grams sugar|1 egg|Salt.', 'Cream the butter with the sugar, egg, and salt into one soft mixture. First add the sifted flour and then the coconut. Mix everything thoroughly. Butter a baking tray. Shape the dough into small balls and place them on the baking tray. Bake them in a very moderate oven heat (150°) for 30 minutes until done. They are ready when lightly colored and loose on the baking tray.', 3, 4428);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (50, 'Mocha cream', '1/4 l whipping cream|1 packet whipped cream stabilizer|2 1/2 tablespoons white caster sugar|1 tablespoon strong coffee|1 dl chocolate pudding|4 cookies|25 grams mocha beans', 'Whip the cream with whipped cream stabilizer and sugar until stiff in a bowl. Spoon 2 tablespoons of whipped cream into a piping bag. Beat the coffee and chocolate pudding into the rest of the whipped cream. Divide the whipped cream mixture over 4 glasses and refrigerate until use. Decorate with a tuft of whipped cream and chocolate mocha beans.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (51, 'Cream puffs', '1 1/2 dl water|Pinch of salt|75 grams margarine|90 grams sifted flour|2 to 3 eggs', 'Bring the water with some salt and the margarine to a boil while stirring. Remove from the heat and stir in the sifted flour all at once with a wooden spoon. Return briefly to the heat until the dough comes away from the sides as a ball. Remove from the heat and add the 2 eggs + 1 yolk one by one. The dough should fall from the spoon in chunks. Beat the dough until airy and glossy with the mixer. Using 2 teaspoons (or a piping bag), spoon or pipe 30 mounds onto the greased baking tray with plenty of space between them (tip 9). Place the tray in the middle of the oven - 200° - and bake the puffs for 20 to 25 minutes until golden. Then leave them in the switched-off and opened oven for another 5 minutes and let them dry out on a rack. Fill them with sweetened whipped cream, dust with powdered sugar, and decorate with paper umbrellas.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (52, 'Cake with nut crust', '175 grams butter|150 grams sugar|Salt|3 eggs|1 egg yolk|200 grams self-raising flour|1 packet vanilla sugar|Butter for greasing|1 egg|150 grams sugar|200 grams ground hazelnuts', 'Beat the butter with the sugar until frothy. Add the egg yolks. Mix in the flour and vanilla sugar. Fold in the egg whites beaten stiff with salt. Spoon the batter into a greased springform tin of 26 cm diameter. For the nut crust, beat the egg and egg white, sugar, and a pinch of salt until frothy. Mix in the ground nuts. Spoon the mixture on top of the batter in the tin. Bake the cake in an oven preheated to 175° for about 50 minutes. Remove the cake from the tin and cut into 12 slices.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (53, 'Tiramisu (classic)', '500 grams Mascarpone Galbani|1.25 dl strong coffee|4 egg yolks|2 egg whites|100 grams powdered sugar|2 cl Amaretto|200 grams boudoirs|3 tablespoons cocoa powder', 'Arrange the biscuits and sprinkle them with the coffee. Make a batter with the egg yolks, sugar, and liqueur. Add the mascarpone. Beat the egg whites to a light foam and fold very carefully into the batter. Arrange the biscuits in three layers and add some cream between each layer. Leave the dish in the refrigerator for 2 to 4 hours. Sprinkle the whole with cocoa powder before serving.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (54, 'Thick courgette-leek soup', '2 courgettes (+/- 400 grams)|2 leeks (+/- 400 grams)|Salt|1 onion|Butter or margarine|2 tablespoons flour|1 herb bouillon tablet|1 dl coffee cream|1 tablespoon lemon juice|1 tablespoon dill (frozen)', 'Wash the courgettes and remove the tops. Slice them. Cut the slices into 4. Clean the leeks, slice into rings, and wash. Put courgette, leek, salt, and 1/2 l water into a pan and bring to a boil. Let cook gently for 5 minutes. Scoop 16 pieces of courgette out of the pan and keep for garnish. Let the rest cook for another 10 minutes. Meanwhile, peel and chop the onion. Purée the courgette-leek mixture. Add water up to 8 dl. Heat butter in a pan and fry the onion gently for about 3 minutes. Stir in the flour and, while stirring, add the leek-courgette mixture little by little. Keep stirring until the soup thickens. Crumble the bouillon tablet over it. Let simmer gently for about 5 minutes. Add coffee cream, lemon juice, and dill. Season with pepper and salt. Spoon into 4 soup bowls. Garnish with courgette slices. You can also use fresh broth and parsley instead of dill.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (55, 'Stuffed chicken soup', '1 chicken of about 1.200 kg|1 large leek|2 sprigs green celery|bay leaf|1 large onion|100 grams bacon|Solo|50 grams rice|300 grams carrots|Parsley|50 grams grated Parmesan|Pepper and salt', 'Place the chicken in 2 l water and bring to a boil, together with the green part of the leek cut into large pieces, the celery leaves, and the bay leaf. After 30 minutes of cooking, remove the chicken from the broth and test whether it is done. Let the broth cook for another 15 minutes and strain it. Finely chop the onion and cut the bacon into small cubes. Melt a little Solo in a large pan and sauté the onion and bacon in it. Pour in the broth and add the rice (vermicelli). Cut the carrots into julienne and add these to the broth as well. After 10 minutes of cooking, add the finely chopped leek, celery, and parsley. Meanwhile, debone the chicken and cut the meat into strips. Add this to the soup just before the end of the cooking time. Season with pepper and salt. Sprinkle the soup with Parmesan and eat with baguette.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (56, 'Mother''s vegetable soup', '--- Broth: ---|2 l water|1 onion|carrots|Some parsley - leaf celery - bay leaf - piece of mace|A clove|Minced meat|Breadcrumbs|Salt and pepper|Nutmeg|--- Soup vegetables: ---|Cauliflower - onion - celeriac - green beans - carrots - leek|Mushrooms - Brussels sprouts - vermicelli.', 'Make a strong broth with the meat, vegetables, and spices. Meanwhile, for the meatballs, mix the minced meat with pepper, breadcrumbs, salt, and nutmeg. Add the vegetables, meatballs, and, if desired, the soup meat cut into small pieces. At the end, cook the mushrooms and vermicelli along until done. Add a few meat bouillon cubes to taste. Finish with parsley and leaf celery. Optionally add some more salt and pepper.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (57, 'Goulash soup', '1/2 kg beef stew meat (cut into small pieces)|300 grams onions|1/2 dl oil|paprika powder|1 tablespoon tomato paste|1 dl red wine|1 l broth|2 cloves garlic|Green herbs|4 large potatoes|Salt and pepper|1 bay leaf|carrots', 'Peel the onions and chop finely. Heat the oil and sauté the onions until golden brown. Thin with tomato paste and heat until the sauce starts to brown. Stir in the paprika powder and let fry briefly over high heat. Add red wine and a cup of the broth. Let simmer for 10 minutes and then add the meat pieces and let them brown briefly in the sauce. Add the carrots, spices, and remaining broth. Close the steam pot and steam for 30 minutes. Then add the potatoes cut into cubes and let them cook until done. Season the soup to taste and decorate with the bell peppers cut into paper-thin strips. Heat only very briefly. Delicious, good as a meal soup.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (58, 'Mexican soup', '100 g onion|1 green bell pepper|2 red bell peppers|Small box tomato paste|500 grams corn|300 grams ham in one chunk|Broth', 'Let the onion, ham, and green bell pepper stew in pieces in a little butter. Add 1 l hot broth. Let simmer for 15 minutes on low heat. Then add the corn kernels + liquid + red bell pepper cut into cubes + 3 tbsp tomato paste. Let boil through, season with black pepper, thyme, and garlic. Optionally you can also add carrots and peas or beans.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (59, 'Curry soup with mussels', '1 1/2 tablespoons butter|3 tablespoons chopped onion|1 1/2 tablespoons flour|1 small tablespoon curry powder|1 dl fresh cream|250 grams cooked mussels from the shell|Freshly ground pepper and salt', 'Sauté the onion in the butter, stir in the flour and curry, let it stew briefly, and pour in the broth and strained cooking liquid. Stir and let thicken slightly over low heat. Stir in the fresh cream and season with pepper and salt. Add the mussels just before serving and let them heat briefly in the soup. Serve with fresh baguette.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (60, 'Mustard fish soup', '½ onion|250 grams potatoes|Butter|2 tsp curry powder|1 herb bouillon tablet|150 grams cod fillet|1 spring onion|1 ½ tbsp coarse mustard|1 egg|3 tablespoons cream|1 tablespoon lemon juice|1 sprig parsley|Salt and pepper', 'Chop the onion, peel the potatoes and cut into pieces. Melt butter. Fry the onion and curry powder for about 3 minutes. Add the potatoes, bouillon tablet, and ½ l water and let cook gently for 25 minutes. Rub through a sieve. (I blend it briefly.) Add water up to 7 dl. Cut the fish into strips. Remove the outer leaf from the spring onion and slice into thin rings. Stir the soup and mustard together. Add the fish and bring to a boil. With the lid on the pan, let cook gently for about 6 minutes. Meanwhile, separate the egg and beat the yolk with the cream. Off the heat, add this to the soup while stirring. Stir in lemon juice and spring onion. Season with pepper and salt and sprinkle finely chopped parsley over it.', 10, 4560);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (61, 'Pumpkin soup', 'Pumpkin|onion|leek|Cream|Pepper and salt|Broth|Parsley', 'Peel the pumpkin, remove the seeds, and cut into cubes. Finely chop the onion(s) and fry in butter until golden yellow. Let the pumpkin stew briefly with it. Add the leek cut into rings. Pour in the broth and cook everything until tender. Blend briefly. Add cream, pepper, and salt and let it boil through briefly. Sprinkle generously with parsley.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (62, 'Soup with Maredsous cheese', '3 large onions|3 cloves garlic|3 large potatoes|1 small can tomato paste|3 meat stock cubes|1 tub Maredsous Double Cream processed cheese (200g)|1.5 l water', 'Peel the onions, peel the potatoes, and chop them finely. Press the garlic cloves. Put the water in a cooking pot and add the vegetables, garlic, and tomato paste. Bring to a boil. As soon as it boils, add the processed cheese and the stock cubes and stir well. As soon as the whole thing boils again, let it cook over low heat for 30 minutes. Then blend. Serve hot, decorated with some fried bread cubes and parsley.', 10, 11678);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (63, 'Vegetable soup with salami', 'Broccoli|Spring onions|Cherry tomatoes|Carrots|Mushrooms|Vermicelli|Cervelat sausage|Clove of garlic|Some spinach leaves|Fresh broth and bouillon cubes|Thyme|Rosemary', 'Divide the broccoli into florets, cut the spring onions diagonally into small pieces, cut the tomatoes in half, slice the carrots (you get nice ridges if you use a crinkle knife), and cut the mushrooms into thin slices. Dip the spinach briefly in hot water and tie it into a small knot. Put the mushrooms, carrots, spring onions, thyme, rosemary, garlic, and bouillon cubes into the hot broth. Let boil briefly. Remove the rosemary and thyme and add pepper and salt. Only add the salami and tomatoes at the very last moment.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (64, 'Southern vegetable soup', '1 l chicken broth|1 green and 1 red bell pepper|1 small zucchini|1 small fennel bulb|1 eggplant|2 tablespoons olive oil|1 clove garlic|1 tablespoon chopped basil|Salt', 'Wash the vegetables, remove the seeds and white membranes from the bell peppers. Cut the fennel greens from the bulb. Cut the vegetables into very small pieces. Sauté the crushed garlic clove in the hot oil until translucent. Add the vegetable julienne and stir-fry for 2 minutes. Pour in the chicken broth, bring to a boil, and let simmer for at most 10 minutes. Season to taste and garnish the soup with the chopped basil. A soup that you can serve both hot and slightly chilled. Serve with garlic baguette.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (65, 'Chop choy - Filipino style', '1 pack ''stir fry chop choy mix'' (available in a good Asian store)|1 glass water|1/2 kg meat cut into serving pieces|2 tablespoons cooking oil|1/2 kg mixed vegetables such as cauliflower - broccoli - bell pepper - mushrooms - corn - soybean sprouts - onion and/or carrots', 'Dissolve the ''stir fry chop choy mix'' in water. Bring the oil to temperature in a wok and add vegetables and meat. Add the dissolved chop choy mix too and let cook over high heat until the sauce thickens and the vegetables are soft.', 1, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (66, 'Pancit Canton - Filipino style', '227g Canton noodles (available in a good Asian store)|1/4 kg meat cut into small pieces|2 tablespoons cooking oil|Mixed vegetables: flat beans - red bell peppers - Chinese cabbage - onion and carrots|a little garlic|pancit canton mix (available in a good Asian store)', 'Place the Canton noodles in boiling water for 1 minute. Then let them drain in a colander. Heat oil in a wok and add garlic and onion. Then add the meat with the vegetable mix and the noodles with the pancit canton mix. Let everything cook well for 2 minutes.', 1, 4226);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (69, 'Pasta with spinach and cream cheese', '200-250 grams pasta - e.g. tagliatelle|1 vegetable bouillon cube|200 grams cooked chopped drained spinach (from a can)|1 chopped shallot|100 grams cream cheese|6 leaves fresh basil (or 1 teaspoon dried)|pepper - salt and paprika powder|olive oil', 'Cook the pasta in plenty of water with the vegetable bouillon cube and a splash of oil. Meanwhile, gently sauté the chopped shallot and add the spinach and cream cheese. Keep stirring until the cheese has melted. Optionally add a little water if the sauce is too thick and season with pepper, salt, and paprika powder to taste. At the end, add the basil, crushed or torn. Drain the pasta and mix with the sauce, serve with a fresh salad.', 9, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (70, 'Cheese tart with raspberries', '200 g speculoos|75 g butter|10 g gelatin (about 5 sheets)|1 dl water|8 tablespoons sugar|2 sachets vanilla sugar|25 cL fresh cream|300 g raspberries|200 g cream cheese', 'Put the speculoos cookies in a plastic bag and crush them with a rolling pin. Soften the butter (melt au bain-marie or briefly in the microwave). Put the crushed speculoos in a bowl, add the butter, and mix well. Line the bottom of a baking tin or springform tin (20 cm diameter) with baking paper and spread the cookie dough over it. Soak the gelatin sheets in water until they wrinkle slightly. Then let these sheets melt completely in the water over low heat, without boiling. Add the sugar, mix, and let cool. Mix the fresh cheese with the vanilla sugar. Add the cooled gelatin with sugar and stir well. Whip the fresh cream until stiff and carefully fold it into the cheese mixture. Blend the raspberries and carefully fold the raspberry mousse into the cheese mixture as well. Put the whole batter into the baking tin and let it set in the refrigerator for 24 hours. Enjoy!', 3, 5387);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (71, 'Fennel and carrots stewed in white wine', '3 fennel bulbs|4 carrots|sunflower oil|1.5 tsp dill seed|pepper|salt|1.2 dl white wine', 'Cut the vegetables into pieces. Stew them in the heated oil until tender, together with the herbs. Deglaze with the white wine, let the alcohol evaporate, and serve.', 11, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (75, 'Mulled Wine', '1 liter red wine|5cl cognac or dark rum|1 lemon|1 orange|2 tablespoons honey|100 grams cane sugar|2 cloves|a cinnamon stick', 'Pour the wine into a cooking pot. Add the lemon and the orange, cut into pieces with the peel still on. Stir in the sugar and the honey. Season with the necessary spices. Heat the mixture until it is just below boiling but producing a lot of steam. The longer the drink boils, the more the alcohol evaporates and the flavor is lost. Turn off the stove and let the liquid steep for another 30 minutes. Then strain through a sieve and add 2 glasses of rum or cognac at the end. Let it warm up briefly. Serve carefully in glasses. To protect the glasses from cracking, place a coffee spoon in the glass first.', 2, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (76, 'Zucchini Carpaccio with Dried Tomato', '1 zucchini|4 dried tomatoes in oil|bunch of fresh basil|4 tablespoons olive oil|1 1/2 tbsp lemon juice|1 clove of garlic|1/4 tablespoon salt|black pepper', 'Cut the dried tomatoes into strips. Finely chop the basil leaves and fold in the tomato. Dressing: put oil and lemon juice in a sealable jar. Press garlic into it. Season with salt. Shake well. Wash the zucchini. Use a cheese slicer to shave diagonally into thin slices. Thinly coat four plates with dressing. Arrange the zucchini slices on the plates in an overlapping pattern. Drizzle the rest of the dressing over them, so that all slices are covered. Let stand for about 10 minutes. Sprinkle the zucchini slices with pepper. Distribute the dried tomato with basil on top.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (77, 'Donuts', '20 grams yeast|1 tablespoon sugar|1/2 deciliter lukewarm water|50 grams butter|1/4 liter warm milk|150 grams sugar|1/2 teaspoon nutmeg|2 teaspoons salt|2 large beaten eggs|500 grams flour 50 grams sugar', 'Dissolve the yeast with the tablespoon of sugar in the warm water. Melt the butter in the milk and pour the lukewarm cooled milk into the water with the yeast. Add the next four ingredients. Knead the flour with the liquid into a soft dough. Let the dough rise in a warm place, covered. Then form small balls from the dough and push a hole in the middle with the handle of a wooden spoon. Let them stand in a warm place for another 40 minutes, then deep-fry them until golden brown. Let them drain on paper towels and then roll them through the sugar and cinnamon mixture.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (78, 'Wild Boar Ragout', '800 g wild boar fillets|1 carrot|1 packet dried porcini mushrooms|10 juniper berries|4 cl cognac|2 dl game stock|5 dl wine|red|butter (or oil)|1 tsp olive oil|2 bay leaves|1 shallot|2 tbsp flour|1 sprig of thyme|4 tbsp red currant jelly|2 cloves|1 onion|2 cloves of garlic|pepper|salt', 'PREPARATION: Peel and cut the onion into coarse pieces. Cut the carrot into slices. Peel and crush the garlic cloves. Cut the wild boar into pieces. COOKING: Mix all ingredients - onion, carrot, garlic, juniper berries, cloves, bay leaf, thyme, wine and olive oil - for the marinade. Add the meat. Cover and place in the refrigerator. Marinate overnight. Pat the marinated meat dry. Strain the marinade. Quickly sear the pieces of meat all around in butter or oil. Add the chopped shallot. Stir-fry for 1 minute. Sprinkle in the flour. Stir well. Season with pepper and salt. Add the cognac and let the alcohol evaporate over fairly high heat. Deglaze with the game stock and add enough strained marinade until the meat is just covered. Add the dried porcini mushrooms. Cover and let stew for 1 to 1.5 hours. Stir the red currant jelly into the sauce. Season further if needed. Serve very hot. TIP: Delicious with oven-baked apples filled with cranberries, and with croquettes', 13, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (79, 'Chervil Soup with Oyster Mushrooms', '1 punnet oyster mushrooms (150 g)|2 herb bouillon tablets|1 bag fresh chervil (15 g)|black pepper', 'Bring 1 liter of water to a boil in a pan. Meanwhile, wipe the oyster mushrooms clean with paper towels and cut into strips. Crumble the bouillon cubes over the boiling water and let boil for about 3 minutes. Finely chop the chervil over a cup. Season the soup with pepper. Stir in the chervil. Ladle the soup into four deep plates.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (80, 'Shiitake Mushroom Soup', 'Shiitake mushrooms (Japanese mushrooms)|pepper|salt', 'Cook the mushrooms in the broth and let them simmer gently for at least 20 minutes. The soup is then basically ready, but this soup is best when prepared in the morning and left to stand all day. In the evening it only needs to be reheated and the rich flavor of the shiitake mushrooms will have infused throughout the entire broth. Season the soup with pepper and salt', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (81, 'Mushroom Soup', '1 punnet oyster mushrooms (150 g)|1 punnet shiitake mushrooms (100 g)|1 shallot|1 tablespoon butter or margarine|1 teaspoon sweet soy sauce|2 herb bouillon cubes|1 dl dry sherry', 'Bring 7 dl of water to a boil in a kettle or pan. Meanwhile, wipe the mushrooms clean with paper towels and cut into strips. Peel and finely chop the shallot. Heat butter in a frying pan and cook shallot, mushrooms and sweet soy sauce while stirring for about 3 minutes. Transfer the mushroom mixture to a large pan. Pour in the boiling water. Crumble the bouillon cubes over it and stir well. Add the sherry and let the soup simmer gently uncovered for about 3 minutes.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (82, 'Mushroom Broth', '500 g beef shank|4 liters water|250 g onion|leek|carrot|5 peppercorns|1 bay leaf|100 g white mushrooms|100 g champignons de Paris|100 g shiitake mushrooms|100 g oyster mushrooms|10 g salt|50 g fresh chervil', 'Place the shank in cold water, bring to a boil and skim. Cut onion, carrot, leek into small pieces, wash and add to the broth along with the mushroom stems. Reduce the broth to 2 liters, then strain. Brush the mushrooms clean before use and cut into thin slices. Let the mushrooms cook along for 5 minutes. Season with pepper and salt and add the picked chervil before serving.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (83, 'Mushroom Soup 2', '250 g chestnut mushrooms|150 g oyster mushrooms|100 g chanterelles|1 onion|50 g butter|30 g flour|1 liter broth|1 egg yolk|2 tablespoons|coffee cream|salt|pepper|splash of dry white wine', 'Peel and chop the onion. Clean the mushrooms and cut them into strips and slices. Melt 20 g butter in a frying pan and saut the onion. Add the mushrooms and let them cook with a lid on the pan for about 10 minutes. Melt 30 g butter in another pan and stir in the flour. Pour in part of the broth and keep stirring until a smooth mixture forms. Add the rest of the broth in portions in the same way. Stir the mushrooms with their liquid into the soup. Add a beaten egg yolk while stirring through the soup. Gently heat the soup until it thickens, but do not let it boil. Season the soup with salt and pepper. Optionally add a splash of wine. This dish can be excellently prepared in advance. Only the mixing with egg yolk should be done at the last moment.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (84, 'Oyster Mushroom Soup with Bell Pepper and Corn', '250 g oyster mushrooms|2 tablespoons butter|1 teaspoon basil|3 tablespoons flour|2 vegetable bouillon tablets|1 red bell pepper|1 can corn (340 g)|1 egg|2 tablespoons medium sherry', 'Remove the bottom of the stems from the mushrooms. Cut into strips. Melt butter in a pan. Cook the mushrooms for about 5 minutes. Sprinkle basil and flour over them. Add 1 liter of hot water while stirring. Keep stirring until the soup thickens. Add the bouillon tablets. Simmer gently with a lid on the pan for about 5 minutes. Wash the bell pepper. Remove the seeds and cut into pieces. Drain the corn. Add bell pepper and corn to the soup. Gently heat for about 10 minutes. Stir occasionally. Meanwhile, beat the egg in a small bowl. Remove the soup from the heat. Stir 4 tablespoons of soup into the egg. Add the egg mixture to the soup while stirring. Stir in the sherry. Divide the soup among 4 plates.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (85, 'Clear Chanterelle Soup with Puff Pastry', '250 g chanterelles|1 shallot|25 g butter|1/4 teaspoon thyme|1/4 teaspoon|oregano|1/4|teaspoon sage|1 can clear oxtail soup|5 tablespoons|Madeira|Worcestershire sauce|freshly ground pepper|4 slices|frozen|puff pastry|1 egg', 'Clean the chanterelles, cut large ones into pieces. Peel and very finely chop the shallot. Heat butter in a pan. Gently cook the shallot for about 2 minutes. Add: chanterelles, thyme, oregano and sage. Gently cook along for about 10 minutes, stirring occasionally. Strain the soup, undiluted, over the mixture. Stir in: Madeira, a few drops of Worcestershire sauce and pepper. Remove from heat. Let cool and store covered in a cool place until use. Preheat the oven to 200°C. Spread out the puff pastry and let it thaw for 10 minutes. Separate the egg over 2 small bowls and stir 1 tablespoon of water into the yolk. Fill 4 ovenproof soup bowls with chanterelle soup. Cut the corners off the puff pastry to create a round disc about 2 cm larger than the soup bowls. Brush the puff pastry and rims of the bowls with egg white. Place the puff pastry egg-white side down on the soup bowls, press the edges firmly. Brush the puff pastry with the yolk mixture. Bake in the middle of the oven for about 15 minutes until done and hot. Serve immediately.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (86, 'Game Soup with Mushrooms', '50 g diced|breakfast bacon|mushrooms (chestnut mushrooms - chanterelles - porcini)|1 onion finely chopped|1 tablespoon flour|1 liter game broth|0.5 dl port|0.5 dl heavy cream|salt|pepper|1 tablespoon finely chopped parsley', 'Render the bacon cubes in a large pan. Add the oil and heat it. Saut the mushroom pieces and the finely chopped onion for about 3 minutes in the bacon-oil mixture. Stir the flour through the mixture. While stirring continuously, gradually add the broth bit by bit until a thickened soup has formed. Turn the heat to low, place a lid on the pan and let the soup simmer gently for about 15 minutes. Stir the port and the heavy cream through the soup and season with some salt and pepper. Serve the soup sprinkled with the finely chopped parsley.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (87, 'Stir-Fried Broccoli and Oyster Mushrooms', '1/2 pack pandan rice (250 g)|3 spring onions|1 bag broccoli florets (300 g)|1 punnet oyster mushrooms (150 g)|3 tablespoons oriental stir-fry oil|2 tablespoons soy sauce|150 g salted cashew nuts', 'Bring 4 dl of water to a boil in a pan. Add the rice and cook covered for about 10 minutes until done. Meanwhile, cut the spring onions diagonally into pieces of about 2 cm. Divide the broccoli into smaller florets. Wipe the oyster mushrooms clean with paper towels and halve them. Heat stir-fry oil in a wok. Add spring onion, broccoli and oyster mushrooms and cook while stirring for about 3 minutes. Add soy sauce and 1/2 dl water and let the vegetables cook for about 4 more minutes. Fold the cashew nuts through the vegetables. Spoon the rice into four wide bowls and top with the stir-fried vegetables.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (88, 'Lasagna with Mushrooms', '50 g Parmesan cheese (piece)|salt|1 punnet oyster mushrooms (150 g)|1 punnet large mushrooms (250 g)|1 punnet chanterelles (100 g)|2 tablespoons dry white wine|2 1/2 tablespoons (walnut) oil|approx. 1 teaspoon black and red pepper (McCormick)|1 bag watercress (75 g)', 'Grate the cheese. Cook the lasagna sheets in a pan with plenty of boiling water and salt for about 8 minutes until al dente. Meanwhile, wipe the mushrooms clean with paper towels. Cut the oyster mushrooms into thin strips. Cut the mushrooms into wedges. Cut the chanterelles into slices. Heat butter in a pan. Cook the mushrooms on high heat for about 5 minutes while stirring. Stir in the wine and let it reduce slightly on high heat for about 1 minute. Remove from heat, fold in 2 tablespoons of oil and season the mushroom mixture with salt and half of the pepper. Preheat four plates. Drain the lasagna sheets and halve them widthwise. Drizzle with the rest of the oil. Distribute the watercress over the plates. Spoon 1/3 of the mushrooms onto the watercress. Place half of the lasagna sheets on top. Spoon another 1/3 of the mushrooms onto the lasagna sheets. Cover with the rest of the lasagna sheets. Finally, spoon the remaining mushrooms on top. Sprinkle with grated cheese and the rest of the pepper.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (89, 'Pork Tenderloin with Mushroom Sauce', '1 onion|1 punnet oyster mushrooms (150 g)|1 punnet chestnut mushrooms (250 g)|50 g cooking bacon (deli meat)|1 sprig of parsley|50 g butter or margarine|4 pork tenderloins (150 g each)|salt|pepper|1/2 tablespoon thyme|4 tablespoons marsala (liquor store)|1 tablespoon soy sauce (Chinese Emperor)|1/8 liter heavy cream', 'Preparation time: long! But worth the result. Prepare: Half a day in advance. Peel and halve the onion. Cut the halves into thin rings. Wipe the mushrooms clean with paper towels. Cut the tough stems from the oyster mushrooms. Cut large oyster mushrooms into strips. Cut the mushrooms into slices. Cut the bacon into pieces. Finely chop parsley into a cup. Cooking: Preheat five plates. Heat butter in a frying pan. Cook onion, mushrooms and bacon for about 5 minutes. Meanwhile, cut the pork tenderloins diagonally into slices about 2 cm thick. Flatten the slices with a meat knife. Sprinkle the pork tenderloin with salt, pepper and thyme. Use a slotted spoon to transfer the mushroom mixture from the pan onto a plate. Fry the pork tenderloin in the remaining fat for about 5 minutes, turning halfway. Transfer to a preheated plate and keep warm under aluminum foil. Add to the remaining fat: mushroom mixture, marsala, soy sauce and heavy cream. Bring to a boil and let reduce on high heat for about 2 more minutes. Season with salt and pepper. Arrange the pork tenderloin slices on plates in an overlapping pattern. Pour the mushrooms half over and alongside. Sprinkle with parsley. Serve with green beans with smoked bacon and potato croquettes.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (90, 'Cheese and Oyster Mushroom Tartlet', '4 slices puff pastry (frozen)|3 spring onions|1 punnet oyster mushrooms (150g)|1 tablespoon butter or margarine|2 tablespoons dry white wine|2 teaspoons thyme|2 tablespoons breadcrumbs|100g grated aged cheese (bag of 150g)|3 eggs|1/2 cup creme fraiche (125ml)|pepper|(1/2 tablespoon butter or margarine for greasing|1 tablespoon flour for dusting)|paper towels|4 shallow tart molds approx. 10 cm diameter', 'Preheat the oven to 200 degrees C or gas mark 4. Spread the puff pastry on the counter and let it thaw for about 5 minutes. Meanwhile, clean the spring onions and cut into rings. Wipe the oyster mushrooms clean with paper towels and cut into strips. Heat butter in a pan and cook the oyster mushrooms on high heat while stirring for about 3 minutes. Add spring onion, wine and thyme and let the whole thing cook uncovered for about 3 more minutes, allowing the liquid to evaporate. Let it cool. Meanwhile, grease the molds. Dust the counter with flour. Roll out the puff pastry slices into squares of about 16x16 cm. Line each mold with 1 slice of puff pastry. Cut away excess dough along the edges. Prick holes in the bottom with a fork. Sprinkle the bottoms with breadcrumbs and 2 tablespoons of cheese. In a bowl, beat the eggs with creme fraiche and the rest of the cheese. Season with pepper. Fold in the oyster mushroom mixture. Divide the mixture over the molds. Bake the tartlets on 1 rack below the middle of the oven for about 24 to 30 minutes until light brown and done. Let the tartlets cool in the molds for about 10 minutes. Remove the tartlets from the molds and let them cool further on a cooling rack.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (91, 'Mushroom Pie with Ham', '8 slices frozen puff pastry|1 punnet oyster mushrooms (150 g)|2 shallots|25 g butter|1 tsp thyme|200 g ham cubes|1 egg|1 can veal ragout|1 tablespoon coffee cream|salt|pepper', 'Preparation time: about 15 minutes and 40 minutes in the oven. Preheat the oven to 200 degrees C. Let the puff pastry thaw. Cut the shiitake mushrooms and champignons into slices, cut the oyster mushrooms into strips. Finely chop the shallots. Cook the mushrooms and shallots until the liquid has evaporated. Add thyme, salt and pepper. Roll out 5 slices of dough into a round sheet of 30 cm. Grease a tart pan (diameter 26 cm) and line with the dough sheet. Stir the egg through the ragout and fold in the mushrooms and ham. Distribute the mixture over the tart base. Roll out the other dough slices into a sheet the size of the pan. Place the sheet over the filling. Press the edges closed. Make holes in the top. Brush the top with coffee cream. Bake the pie for about 40 minutes.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (92, 'Pate with Oyster Mushroom Dressing', '1/2 head oak leaf lettuce|8 tablespoons walnut oil|3 tablespoons (red wine) vinegar|1 teaspoon mustard|1/2 teaspoon sugar|salt|freshly ground black pepper|1/4 punnet oyster mushrooms (150 g)|4 slices nut pate approx. 75 g each', 'Clean, wash and drain the lettuce. Stir oil, vinegar, mustard, sugar, salt and pepper into a dressing. Wipe the oyster mushrooms clean with paper towels and chop very finely. Stir into the dressing and set aside for about 5 minutes. Distribute the lettuce over four plates. Place the pate slices in the center. Spoon the oyster mushroom dressing over them. Serve with toast.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (93, 'Oyster Mushrooms with Snow Peas', '1 punnet oyster mushrooms 150 g|100 g snow peas|4 stone leeks|1 tablespoon butter or margarine|1/2 tablespoon (corn) oil|2 cloves of garlic|salt and pepper', 'Wipe the oyster mushrooms clean with paper towels and cut into strips. Clean and wash the snow peas. Clean the stone leeks and cut into rings. Heat butter and oil in a wok or saute pan. Peel the garlic and press it in. Add the snow peas and cook while stirring for about 3 minutes. Add the oyster mushrooms and cook along for about 3 minutes. Add the stone leeks and cook along for about 1 minute. Season with salt and pepper. Delicious with pork tenderloins and pommes duchesses, mashed potato towers.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (94, 'Salad with Field Mushroom', '1 head iceberg lettuce|100 grams field mushroom|(spring) onion|chives', 'Wash and tear the lettuce. Brush the field mushroom clean and cut into slices. Finely chop the onion, cut the chives into pieces. Mix these ingredients together. Dressing: Mix oil, vinegar, a pinch of thyme, mayonnaise and a little bit of sugar together. Pour the dressing over the salad and your salad is ready.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (96, 'Mushroom Soup', '400 grams mushrooms|1 small clove of garlic|25 g butter or margarine|2 herb bouillon cubes|3 drops lemon juice (bottle)|1 dl semi-skimmed coffee milk and cream', 'Wash the mushrooms. Cut them into pieces on the cutting board. Peel the garlic and cut it into very small pieces on the cutting board. Put the butter in the pan and place the pan on the stove. Turn on the heat and let the butter melt. Add the mushrooms and garlic when the foam subsides. Turn the heat to low and let the mushrooms and garlic braise, gently cook for about 10 minutes. Stir occasionally with a wooden spoon. Add the water and the bouillon cubes. Turn the heat higher. Let the soup boil for about 5 minutes. Add the coffee milk and lemon juice to the soup and stir briefly before serving the soup. TIP: Add finely chopped fresh parsley: this gives an extra delicious flavor.', 8, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (97, 'Fake Mushrooms', '2 firm tomatoes|1 cucumber|1 can tuna|2 spoons salad dressing|a pinch of pepper salt and paprika powder', 'Wash the cucumber thoroughly and cut the cucumber into four equal pieces. Cut the cucumber straight so that each piece can stand upright. Hollow out each piece on one side with a spoon. Drain the liquid from the tuna through a colander, mix the tuna with the salad dressing and a pinch of pepper, salt and paprika powder. Fill the four hollowed-out cucumber stumps with the mixture. Cut the tomatoes in half, hollow out the four halves with a spoon, place them on the cucumber stumps. Make small white dots with the mayonnaise on the tomato caps.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (98, 'Pistachio Macarons', '75g pistachios|125g powdered sugar|2 whites of large eggs|15g fine granulated sugar||55g pistachios|250g powdered sugar|125g softly stirred butter', 'Preheat the oven to 180°C (gas mark 4). Chop the pistachios in a food processor together with the powdered sugar (this prevents it from becoming an oily mess) into a kind of flour. Beat the egg whites fairly stiff, but not too dry. Sprinkle the fine granulated sugar on top and continue beating until the egg white is very stiff. Gently fold the foam through the pistachio-sugar mixture. Pipe small rounds onto a lined baking sheet with a smooth nozzle, with a diameter of 1cm. Let them stand for about 10 minutes so that a skin forms. Then place them in the oven and bake for 10 to 12 minutes. They should be firm but not too dry. Remove them from the oven and let them cool on the sheet while you make the filling. Grind the nuts and powdered sugar in the food processor as described above. Stir the butter until creamy and keep stirring while adding the nut flour. Make sure you have a smooth, soft buttercream. Then simply make sandwiches from the macarons with the cream in between. Makes 20 pieces, that is 40 macarons glued together two by two.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (99, 'Cheesecake with Speculoos and Nuts', '250 g speculoos cookies|125 g butter|500 g full-fat fresh cheese|250 g fine sugar|100 g peeled nuts|2 tablespoons flour|3 eggs|25 cl cream', 'Preheat the oven to 180 degrees and meanwhile line a springform pan with baking paper. Grind the nuts and crumble the cookies. Let the butter soften (until soft, not until liquid). Mix the cookies, nuts and butter into a sticky paste and spread the paste over the bottom of the pan. Mix the cheese with the sugar, the flour and the eggs. Then add the cream and stir everything smooth. Pour the cream over the cookie-nut base. Bake the cake for 30 to 40 minutes in the middle of the oven. Check occasionally as the top tends to get too dark quickly.', 3, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (101, 'Velouté soup Agnes Sorel', '2 white leeks (coarsely chopped)|1 celery stalk (coarsely chopped)|2 onions (coarsely chopped)|100 g mushrooms (coarsely chopped)|1.5 l chicken broth or light stock|Lemon juice|Black pepper (freshly ground)|Sea salt|50 g wheat flour|40 g real butter|Cream|1 egg yolk|100 g mushrooms (sliced or brunoise)|100 g cooked chicken (cut into julienne or brunoise)|100 g cooked or smoked beef tongue (cut into julienne or brunoise|you can replace the beef tongue with cooked or smoked ham if desired', 'Melt the butter in a soup pan, add the vegetables and let everything sauté. Sprinkle with the flour and mix well with a spoon. Moisten with the broth or stock and bring to a boil while stirring. Let simmer over low heat for 30 minutes. Put some water and lemon juice in a small saucepan and add the mushrooms (for garnish). Cover with baking paper, place a small plate on top, and cook over high heat for about 5 minutes. Remove the soup from the heat, blend with an immersion blender, and pass through a sieve. Garnish: add the mushrooms, tongue, and chicken to the soup and season with pepper, salt, and lemon juice. Let the whole thing boil for another two minutes. In a small bowl, beat the egg yolk with the cream (both at room temperature), stir in some warm but non-boiling soup. Add this mixture to the soup, return to the heat, and stir until the soup is warmed through again and nicely lightly thickened (Do not boil! - Soup to which a liaison is added should never be boiled, otherwise it will curdle! Of course you can always omit the egg yolk).', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (102, 'Bread with spinach dip sauce', '1 can (400 g) artichoke hearts (finely chopped)|400 g fresh spinach (without stems and finely chopped)|200 g cream cheese (cut into cubes)|130 g mozzarella (grated or in small pieces)|30 g Parmesan cheese (grated)|1/4 teaspoon black pepper|1 clove garlic (pressed)', 'Preheat the oven for 20 minutes at 180° and serve with pieces of bread', 5, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (103, 'Bounty', '1 banana|1-2 tbsp grated coconut|30 g dark chocolate (72% cocoa or more)', 'Mash the banana finely and mix the coconut through the banana. You can also add more coconut if you like that. Shape bounty bars with your hands. Put them in the freezer for at least an hour. Melt the chocolate au bain-marie and take the frozen bounty bars out of the freezer. Dip them in the melted chocolate and place on baking paper. Once you have dipped all the bounty bars in the chocolate, put them back in the freezer until the chocolate has hardened. You can keep these for two weeks.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (343, 'American cookies', '250g wheat flour|8g baking powder|120g sugar|100g grated chocolate|10g cocoa powder|1 vanilla pod|200g butter|1 egg', 'Mix the flour, sugar, and cocoa powder and then add the butter (in pieces). Stir in the egg as well. Scrape the seeds out of the opened vanilla pod and add together with the grated chocolate to the dough. Mix everything well and place the dough onto a sheet of cling film, then let it rest in the refrigerator for half an hour. Meanwhile, preheat the oven to 175 degrees and line the baking tray with baking paper. Roll small balls from the dough, place them on the baking tray with some space in between, flatten them, and bake for about 20 minutes until done.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (344, 'Chocolate fondue', 'Milk chocolate|dark chocolate|white chocolate|6 dl cream|marshmallows|chocolate candies|sprinkles|chocolate sprinkles|chopped nuts', 'Melt the chocolate in separate bowls and stir a little cream into each bowl of chocolate. Place the bowls on the table, thread the marshmallows onto a stick, and dip into the topping of your choice.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (345, 'Chocolate cups', '150g dark and 150g milk chocolate|50g butter|2-3 tbsp speculoos spread|salt', 'Melt the chocolate with the butter and coat paper cupcake liners with a thin layer. Let set briefly in the refrigerator. Fill the liners with some speculoos spread, place some melted chocolate on top, and let set again in the refrigerator. Finish with a pinch of salt and serve immediately.', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (346, 'Nut pralines', '200g milk and 200g white chocolate|100g almonds and 100g pecans', 'Spread the nuts over an oven dish and roast them golden brown at 160 degrees. Meanwhile, melt the chocolate, each in a separate bowl. Dip the nuts completely into the chocolate using tweezers or a fork and place them on a sheet of baking paper. Put the baking tray in the freezer or refrigerator for fifteen minutes and then store in a sealed jar ... or just eat them right away!', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (347, 'Chicken soup with red curry', '500 ml chicken broth|100 g chicken thigh meat|1 pomodori tomato|30 g soybean sprouts|1 spring onion|1/2 carrot|celery stalk|1 tbsp red curry paste|25 g corn kernels|handful cilantro|1 tsp sunflower oil|Pinch of black pepper', 'Preheat the oven to 180 degrees. Heat the chicken broth. Mix the chicken thigh meat with the sunflower oil and black pepper, bake for about 15 minutes in the oven, let cool, and cut into thin strips. Finely chop the cilantro, cut the tomatoes into cubes, the carrot into strips, the celery into strips, and the spring onion into thin rings. Add the carrot, celery, and red curry paste to the chicken broth and boil briefly. Add the tomato, chicken strips, soybean sprouts, corn kernels, and spring onions to the chicken broth and heat briefly. Garnish with the cilantro.', 10, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (355, 'Oatmeal cookies', '200 g oats', 'Mix all ingredients in a bowl. Preheat the oven to 175 °C. Make small balls and flatten them on a baking tray into cookie shapes. Bake for 25 minutes', 6, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (359, 'Tiramisu with strawberries', '500 g mascarpone|2 eggs|2 punnets strawberries|50 g sugar|1 sheet gelatin|1 dl strawberry liqueur|strawberry coulis', 'Soak the gelatin sheet in cold water. Beat the egg yolks with the sugar into an almost white, airy mixture (+/- 8-10 min). Heat the strawberry liqueur and dissolve the squeezed gelatin in it. Mix the mascarpone with the egg yolk mixture and the strawberry liqueur. Beat the egg whites until stiff and fold them into the mascarpone mixture. Arrange a layer of halved strawberries in a springform tin and pour 1/3 of the cheese mixture over it. Repeat the same way in 3 layers until everything is used up. Refrigerate for at least 3 hours to set. Garnish the tiramisu with a few nice strawberries and fresh mint. Serve with strawberry coulis. You can also use a handful of strawberries instead of strawberry liqueur, blended and sweetened. Then heat a splash of cognac and dissolve the gelatin in it and mix it into the strawberries. Bring frozen fruit (raspberries or mixed red fruit), 100 g icing sugar, and 1 dl water to a boil, let the fruit simmer in it for 5 minutes, and let cool. Fold the juice of the frozen fruit into the mascarpone instead of blended strawberries. Suggestion: fill the bottom of long drink glasses with strawberries and a layer of tiramisu, fill the glass in layers, and decorate with fresh strawberries and fresh mint or the frozen fruit. That also seems like a lovely festive dessert.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (360, 'Egg liqueur', 'Can of condensed milk (305ml)|10 egg yolks|205g sugar|20g vanilla sugar|200ml alcohol 90 degrees.', 'Beat the egg yolks in a large bowl with the condensed milk. Add the sugar and vanilla sugar and stir well. Put a saucepan of water on the stove and bring to a boil. Place the bowl over the pan with warm water. The bowl must not touch the water, otherwise you will get scrambled eggs. Start beating immediately. Keep beating until the mixture thickens. Finally add the alcohol little by little and beat well each time. Divide into jars and let cool.', 2, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (361, 'Egg liqueur mascarpone mousse', '6 tablespoons egg liqueur|3 eggs|2 tablespoons sugar', 'Beat the egg yolks with the sugar until pale. Add mascarpone. Add egg liqueur. Beat the egg white until stiff and add to the mixture. Make sure the whole remains very airy. Divide over the glasses.', 7, 0);
INSERT INTO recipe (id, title, ingredients, preparation, category_id, view_count) VALUES (362, 'Onion soup', '6 large onions|thinly sliced|50 grams unsalted butter|2 cloves garlic|finely chopped|100 ml white wine|1 liter beef broth|4 slices baguette|100 grams grated Gruyère cheese|Sprigs of fresh thyme (for garnish)|2 tablespoons cognac (optional)|Salt and pepper to taste', 'Melt the butter in a large pan over medium heat. Add the olive oil to prevent the butter from burning. Add the sliced onions to the pan and fry them slowly until golden brown, about 25-30 minutes. Stir occasionally to prevent burning. Caramelizing the onions is an essential part of the recipe, so take your time! Add the garlic and cook for another 1-2 minutes. Deglaze with white wine and scrape the browned bits from the bottom of the pan. Let the wine reduce for 2 minutes. Add the beef broth and bring the soup to a boil. Lower the heat and let the soup simmer gently for 20-30 minutes. Taste and season with salt and pepper. Optional: add the cognac for extra depth of flavor. Preheat the oven to 180 degrees. Toast the baguette lightly in the oven until crisp, about 5 minutes. Pour the soup into ovenproof bowls. Place a slice of toasted baguette on the soup and sprinkle generously with grated Gruyère over it. Put the bowls in the oven and let the cheese melt and turn lightly golden brown, about 10 minutes. Remove the soup from the oven and garnish with fresh thyme. Serve immediately.', 10, 0);